package com.bank.finhealth.service;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Longest Increasing Subsequence in n log n via smallest-tail binary search.
public class FinancialHealthService {
    private static final Logger log = Logger.getLogger(FinancialHealthService.class.getName());

    public int longestRisingRun(int[] balances) {
        List<Integer> tails = new ArrayList<>();           // tails[k] = smallest tail of length k+1
        for (int x : balances) {
            int pos = lowerBound(tails, x);                // first tail >= x (strict increase)
            if (pos == tails.size()) tails.add(x);         // x extends the longest run
            else tails.set(pos, x);                        // x makes an existing length cheaper
        }
        final int result = tails.size();
        log.info(() -> "Longest strictly rising run = " + result);
        return result;
    }

    private int lowerBound(List<Integer> tails, int target) {
        int lo = 0, hi = tails.size();                     // binary search for first >= target
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (tails.get(mid) < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}
